#pragma once

#include "utf8_path.hpp"

#include <algorithm>
#include <filesystem>
#include <string>
#include <system_error>

namespace acecode {

// Apply only to names generated by ACECode, never to an existing identity or
// a user-supplied path. Protocol UUIDs keep their standard representation.
inline std::string generated_file_name(std::string name) {
    std::replace(name.begin(), name.end(), '-', '_');
    return name;
}

// Reuse an existing legacy resource instead of opening a second, empty store.
// Legacy wins if both names exist; leave reconciliation to the owning module.
inline std::filesystem::path compatible_generated_path(
    const std::filesystem::path& directory, const std::string& legacy_name) {
    const auto legacy = directory / path_from_utf8(legacy_name);
    if (legacy_name.find('-') == std::string::npos) return legacy;
    std::error_code ec;
    if (std::filesystem::exists(legacy, ec) || ec) return legacy;
    return directory / path_from_utf8(generated_file_name(legacy_name));
}

} // namespace acecode
